def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = [0, 0]  # stem above bar; stem below bar

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == 2 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            if len(comp) != 4:
                continue
            row_counts = {}
            for x, y in comp:
                row_counts[x] = row_counts.get(x, 0) + 1
            if sorted(row_counts.values()) != [1, 3]:
                continue
            singleton_row = next(x for x, n in row_counts.items() if n == 1)
            triple_row = next(x for x, n in row_counts.items() if n == 3)
            counts[0 if singleton_row < triple_row else 1] += 1

    out = [[0] * 6 for _ in range(3)]
    pip_slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for kind, color in enumerate((3, 1)):
        n = min(counts[kind], 4)
        for rr, cc in pip_slots[:n]:
            out[rr][kind * 3 + cc] = color
    return out
